package com.optarena.app

fun interface Clock {
    fun now(): Long
}

class Cache<K, V>(
    private val capacity: Int,
    private val ttlMillis: Long,
    private val clock: Clock = Clock { System.currentTimeMillis() },
) {
    private data class Entry<V>(val value: V, val storedAt: Long)

    private val store = LinkedHashMap<K, Entry<V>>(16, 0.75f, true)

    fun put(key: K, value: V) {
        store.remove(key)
        if (store.size >= capacity) {
            val oldest = store.keys.firstOrNull()
            if (oldest != null) store.remove(oldest)
        }
        store[key] = Entry(value, clock.now())
    }

    fun get(key: K): V? {
        val entry = store[key] ?: return null
        if (clock.now() - entry.storedAt >= ttlMillis) {
            store.remove(key)
            return null
        }
        return store[key]?.value
    }
}

