package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Test

private class FakeClock(var time: Long = 0L) : Clock {
    override fun now(): Long = time
}

class CacheTest {
    @Test
    fun capacityEvictsLeastRecentlyUsed() {
        val clock = FakeClock(0)
        val c = Cache<String, Int>(2, 1000, clock)
        c.put("a", 1); clock.time = 1
        c.put("b", 2); clock.time = 2
        c.get("a"); clock.time = 3
        c.put("c", 3); clock.time = 4
        assertEquals(1, c.get("a"))
        assertNull(c.get("b"))
        assertEquals(3, c.get("c"))
    }

    @Test
    fun getRefreshesRecency() {
        val clock = FakeClock(0)
        val c = Cache<String, Int>(2, 1000, clock)
        c.put("a", 1); clock.time = 1
        c.put("b", 2); clock.time = 2
        c.get("a"); clock.time = 3
        c.get("b"); clock.time = 4
        c.put("c", 3); clock.time = 5
        assertNull(c.get("a"))
        assertEquals(2, c.get("b"))
    }

    @Test
    fun ttlExpiryIndependentOfCapacity() {
        val clock = FakeClock(0)
        val c = Cache<String, Int>(5, 10, clock)
        c.put("a", 1)
        clock.time = 9
        assertEquals(1, c.get("a"))
        clock.time = 10
        assertNull(c.get("a"))
    }
}
